input.command:
python3 - <<'EOF'
import os,glob,time,json
cut=time.mktime(time.strptime('2026-09-22','%Y-%m-%d'))
base=os.path.expanduser('~/.claude/projects')
for d in sorted(os.listdir(base)):
    if 'temps-chantier' not in d.lower() and 'tempschantier' not in d.lower(): continue
    fs=[f for f in glob.glob(os.path.join(base,d,'*.jsonl')) if os.path.getmtime(f)>=cut]
    if fs: print(d, len(fs), sum(os.path.getsize(f) for f in fs)//1024,'KB')
# codex: cwd per session
import re
cnt={}
for day in ['22','23','24','25']:
    for f in glob.glob(os.path.expanduser(f'~/.codex/sessions/2026/09/{day}/*.jsonl')):
        with open(f) as fh:
            first=fh.readline()
        try:
            j=json.loads(first); cwd=j.get('payload',{}).get('cwd','?')
        except Exception: cwd='?'
        key=(day,cwd)
        cnt.setdefault(key,[0,0]); cnt[key][0]+=1; cnt[key][1]+=os.path.getsize(f)//1024
for k,v in sorted(cnt.items()):
    if 'emps' in k[1] or 'hantier' in k[1]: print(k,v)
EOF

